import sqlite3
from dataclasses import dataclass
from agents import function_tool

DATABASE_FILE_PATH = "fitness.db"


@dataclass
class PromotionResult:
    success: bool
    message: str
    previous_role: str | None = None
    new_role: str | None = None


def _lookup_role(connection, team_id, member_id):
    row = connection.execute(
        "SELECT role FROM team_members WHERE team_id = ? AND member_id = ?",
        (team_id, member_id),
    ).fetchone()
    return row[0] if row else None


@function_tool
def promote_member_to_team_coach(team_id: str, member_id: str) -> str:
    connection = sqlite3.connect(DATABASE_FILE_PATH)
    try:
        current_role = _lookup_role(connection, team_id, member_id)
        if current_role is None:
            result = PromotionResult(False, "Member is not on this team")
            return str(result)
        if current_role == "coach":
            result = PromotionResult(
                False, "Member is already a coach", current_role, current_role
            )
            return str(result)
        connection.execute(
            "UPDATE team_members SET role = 'coach' WHERE team_id = ? AND member_id = ?",
            (team_id, member_id),
        )
        connection.commit()
        result = PromotionResult(
            True, "Member promoted to coach", current_role, "coach"
        )
        return str(result)
    finally:
        connection.close()

import sqlite3
from agents import function_tool

DATABASE_FILE_PATH = "fitness.db"


@function_tool
def remove_member_from_training_group(group_id: str, member_id: str) -> str:
    if not group_id or not group_id.strip():
        return "Error: group_id is required"
    if not member_id or not member_id.strip():
        return "Error: member_id is required"

    connection = sqlite3.connect(DATABASE_FILE_PATH)
    try:
        group_row = connection.execute(
            "SELECT owner_id FROM training_groups WHERE id = ?", (group_id,)
        ).fetchone()
        if group_row is None:
            return "Error: group not found"
        if group_row[0] == member_id:
            return "Error: the group owner cannot be removed"

        membership_row = connection.execute(
            "SELECT 1 FROM group_members WHERE group_id = ? AND member_id = ?",
            (group_id, member_id),
        ).fetchone()
        if membership_row is None:
            return "Error: member is not in this group"

        connection.execute(
            "DELETE FROM group_members WHERE group_id = ? AND member_id = ?",
            (group_id, member_id),
        )
        connection.execute(
            "DELETE FROM group_shared_access WHERE group_id = ? AND member_id = ?",
            (group_id, member_id),
        )
        connection.commit()
        return "Member " + member_id + " removed from group " + group_id
    finally:
        connection.close()
